static char *k_to_str(Value v, StrA *strs, ListHeap *lists) {
  char buf[64];
  if (v.tag == TAG_I64) {
    snprintf(buf, sizeof(buf), "%lld", (long long)v.payload);
    return xstrdup(buf);
  }
  if (v.tag == TAG_F64) {
    snprintf(buf, sizeof(buf), "%g", f64_bits(v));
    return xstrdup(buf);
  }
  if (v.tag == TAG_STR) {
    if (v.payload < 0 || (size_t)v.payload >= strs->len) die("bad str");
    return xstrdup(strs->data[v.payload]);
  }
  if (v.tag == TAG_LIST) {
    ValA *L;
    char *out;
    size_t cap, len, i;
    if (v.payload < 0 || (size_t)v.payload >= lists->len) die("bad list handle");
    L = &lists->data[v.payload];
    cap = 32;
    len = 0;
    out = (char *)malloc(cap);
    if (!out) die("oom");
    out[len++] = '[';
    for (i = 0; i < L->len; i++) {
      char *part = k_to_str(L->data[i], strs, lists);
      size_t pl = strlen(part);
      size_t need = len + pl + 4;
      if (need > cap) {
        while (need > cap) cap *= 2;
        out = (char *)xrealloc(out, cap);
      }
      if (i) {
        out[len++] = ',';
        out[len++] = ' ';
      }
      memcpy(out + len, part, pl);
      len += pl;
      free(part);
    }
    if (len + 2 > cap) out = (char *)xrealloc(out, len + 2);
    out[len++] = ']';
    out[len] = 0;
    return out;
  }
  return xstrdup("?");
}

static unsigned char *k_read_bytes(const char *path, size_t *out_len) {
  FILE *f = fopen(path, "rb");
  long sz;
  unsigned char *buf;
  if (!f) return NULL;
  if (fseek(f, 0, SEEK_END) != 0) { fclose(f); return NULL; }
  sz = ftell(f);
  if (sz < 0) { fclose(f); return NULL; }
  rewind(f);
  buf = (unsigned char *)malloc((size_t)sz + 1);
  if (!buf) { fclose(f); return NULL; }
  if (fread(buf, 1, (size_t)sz, f) != (size_t)sz) { free(buf); fclose(f); return NULL; }
  fclose(f);
  if (out_len) *out_len = (size_t)sz;
  return buf;
}

